mapper.sql:
WHERE candidate.tenant_id = #{tenantId}
  AND candidate.deleted = 0
  AND candidate.supplier_code IS NOT NULL
  AND TRIM(candidate.supplier_code) <> ''
  AND candidate.supplier_name IS NOT NULL
  AND TRIM(candidate.supplier_name) <> ''

    AND candidate.supplier_code LIKE CONCAT('%', #{supplierCode}, '%')


    AND candidate.supplier_name LIKE CONCAT('%', #{supplierName}, '%')


    AND candidate.status = #{status}


    AND candidate.scope_id = #{scopeId}


    AND candidate.scope_id IN

        #{scopeId}
